35	        return HcclAllReduceInner(sendBuf, recvBuf, count, dataType, op, comm, stream);
36	    }
37	    CHK_PRT_RET(count == 0, HCCL_WARNING("input count is 0, return all reduce success"), HCCL_SUCCESS);
