39	    HcclUs startut = TIME_NOW(); // 走老流程的判断时间不统计在内
40	    OpParam param;
41	    CHK_RET(AllReduceInitAndCheck(comm, sendBuf, recvBuf, count, dataType, op, stream, param));
42	
43	    /* 接口交互信息日志 */
