45	
46	    // 执行AllReduce
47	    CHK_RET_AND_PRINT_IDE(AllReduceOutPlace(sendBuf, recvBuf, count, dataType, op, comm, stream, param), param.tag);
48	
49	    CHK_RET(LogHcclExit("HcclAllReduce", param.tag, startut));
50	
51	    return HCCL_SUCCESS;
52	}
